import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const generatedAssets = path.resolve(root, 'public', 'assets');
if (process.env.VERCEL !== '1') {
  // Stale deployment copies would shadow the editable archived assets locally.
  // This folder is generated by this script and excluded from Git.
  async function verifyGenerated(dir) {
    for (const entry of await fs.readdir(dir, { withFileTypes: true })) {
      const file = path.join(dir, entry.name);
      if (entry.isSymbolicLink()) throw new Error('Unexpected symlink in generated assets');
      if (entry.isDirectory()) await verifyGenerated(file);
      else await fs.access(path.join(root, 'assets', path.relative(generatedAssets, file)));
    }
  }
  try {
    await fs.access(generatedAssets);
    if (generatedAssets !== path.join(root, 'public', 'assets') || !generatedAssets.startsWith(root + path.sep)) throw new Error('Generated asset path outside workspace');
    await verifyGenerated(generatedAssets);
    await fs.rm(generatedAssets, { recursive: true, force: true });
    console.log('Removed stale generated deployment copies; local assets use the compatibility route.');
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
}
if (process.env.VERCEL === '1') {
  const manifest = {};
  async function scan(dir) {
    for (const entry of await fs.readdir(dir, { withFileTypes: true })) {
      const file = path.join(dir, entry.name);
      if (entry.isDirectory()) await scan(file);
      else manifest[path.relative(root, file).split(path.sep).join('/')] = true;
    }
  }
  await scan(path.join(root, 'assets'));
  await fs.mkdir(path.join(root, 'public'), { recursive: true });
  await fs.cp(path.join(root, 'assets'), path.join(root, 'public/assets'), { recursive: true });
  // The platform reserves /_next/image even with custom rewrites. Point the
  // deployment's archived image loader at our equivalent image endpoint.
  for (const file of Object.keys(manifest).filter(file => file.endsWith('.js'))) {
    const target = path.join(root, 'public', file);
    const source = await fs.readFile(target, 'utf8');
    if (source.includes('/_next/image')) await fs.writeFile(target, source.replaceAll('/_next/image', '/api/reference-image'));
  }
  await fs.writeFile(path.join(root, 'reference-assets.json'), JSON.stringify(manifest));
  console.log('Prepared ' + Object.keys(manifest).length + ' assets for Vercel static delivery.');
}
